// src/lib/site.ts
import { createBlockRegistry, createSchema } from 'uncial/core';
import { defineSite } from 'uncial-cms';
import { siteOptions } from '../../site.options.js';

interface Link {
	label: string;
	href: string;
}

const noBlocks = createBlockRegistry([]);
const isSitePath = (value: unknown) => typeof value === 'string' && value.startsWith('/');
const link = {
	itemLabel: 'link',
	fields: {
		label: { default: '', required: true },
		href: { default: '/', required: true, validate: isSitePath }
	}
};

const banner = createSchema(noBlocks, {
	metaFields: {
		message: { default: '' },
		visible: { default: false }
	}
});

const menus = createSchema(noBlocks, {
	metaFields: {
		header: { default: [] as Link[], list: link },
		footer: {
			default: [] as Array<{ heading: string; links: Link[] }>,
			list: {
				itemLabel: 'column',
				fields: {
					heading: { default: '', required: true },
					links: { default: [] as Link[], list: link }
				}
			}
		}
	}
});

export const site = defineSite({ ...siteOptions, globals: { banner, menus } });

// src/routes/+layout.server.ts
import { loadGlobal } from 'uncial-cms/sveltekit';
import { site } from '$lib/site.js';

export const load = async () => ({
	banner: await loadGlobal(site, 'banner'),
	menus: await loadGlobal(site, 'menus')
});
